// Class 8 Social Science practice bank, part 1: Natural Resources to World Geography (Exploring Society: India and Beyond, Part 1).
StudyData.addPractice(8, "sst", {
  "natural-resources-and-their-use": {
    mcq: [
      { q: "Which of these is an abiotic resource?", options: ["Fish", "Forests", "Iron ore", "Cattle"], answer: 2, explain: "Iron ore is a mineral, a non-living (abiotic) resource. Fish, forests and cattle come from living things and are biotic.", level: 1 },
      { q: "Sunlight is best described as a", options: ["non-renewable resource", "renewable resource", "fossil fuel", "biotic resource"], answer: 1, explain: "Sunlight is not used up when we use it, so it is renewable. It is also non-living, so it is not biotic.", level: 1 },
      { q: "Which of these is a fossil fuel?", options: ["Wind", "Sunlight", "Flowing water", "Natural gas"], answer: 3, explain: "Coal, petroleum and natural gas are fossil fuels. Wind, sunlight and flowing water are renewable.", level: 1 },
      { q: "Soil forms very slowly from", options: ["weathered rock and the remains of plants and animals", "coal and petroleum", "sea water", "wind alone"], answer: 0, explain: "Soil forms over a very long time from weathered rock mixed with dead plants and animals, so it must be protected.", level: 1 },
      { q: "Most of the water on the Earth is", options: ["fresh and ready to drink", "salty and so not directly usable", "stored only in rivers", "in the form of clouds"], answer: 1, explain: "Most of the Earth's water is salty, so the usable fresh water is only a small part of the total.", level: 1 },
      { q: "Which of these is an example of recycling?", options: ["Using an old jar to store pulses", "Switching off a fan when leaving a room", "Melting waste glass to make new bottles", "Buying fewer packaged items"], answer: 2, explain: "Recycling turns waste into new products. Using the jar again is reuse, and switching off the fan or buying less is reduce.", level: 2 },
      { q: "A village in a dry area builds tanks to collect rain from rooftops and stores it for the dry months.\nWhich conservation practice is this?", options: ["Rainwater harvesting", "Drip irrigation", "Mining", "Deforestation"], answer: 0, explain: "Collecting and storing rain for later use is rainwater harvesting. Drip irrigation releases water slowly to plant roots.", level: 2 },
      { q: "Farmer Harjit waters his orchard through pipes that release water slowly near the roots of each plant, instead of flooding the field.\nWhat is the main benefit of this method?", options: ["It makes the soil salty", "It needs more water", "It turns water into a non-renewable resource", "It saves water by wetting only the roots"], answer: 3, explain: "Drip irrigation delivers water where the plant needs it, so very little is wasted.", level: 2 },
      { q: "Something becomes a resource only when", options: ["it is found deep underground", "people have the knowledge and technology to use it", "it is far from towns", "it is very rare"], answer: 1, explain: "A material is a resource only if people know how to use it and have the technology to do so.", level: 2 },
      { q: "Forests are classified as", options: ["renewable and biotic", "non-renewable and biotic", "renewable and abiotic", "non-renewable and abiotic"], answer: 0, explain: "Forests come from living things (biotic) and can be replaced naturally if used with care (renewable).", level: 2 },
      { q: "Assertion (A): Water is a renewable resource, so it never needs to be conserved.\nReason (R): The usable fresh water is limited and its supply varies from place to place and season to season.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 3, explain: "Water is renewable, but usable water is limited and uneven, so it must still be conserved. The assertion is false and the reason is true.", level: 3, keepOrder: true },
      { q: "Which pair contains only renewable, abiotic resources?", options: ["Forests and fish", "Coal and wind", "Wind and sunlight", "Minerals and sunlight"], answer: 2, explain: "Wind and sunlight are non-living and replaced naturally. Forests and fish are biotic, and coal and minerals are non-renewable.", level: 3 },
      { q: "Which step is best for sustainable development?", options: ["Mining coal as fast as possible to sell it", "Planting trees to replace those cut and shifting to solar power", "Cutting forests for cheap timber without replanting", "Pumping out groundwater faster than rain refills it"], answer: 1, explain: "Replacing what is used and moving to renewable energy meets present needs without harming the needs of future generations.", level: 3 },
      { q: "Region A has plenty of bauxite but no coal, while region B has plenty of coal but no bauxite.\nWhat does this show?", options: ["Minerals are spread evenly over the Earth", "Bauxite is a fossil fuel", "Minerals are renewable", "Minerals are unevenly distributed, so regions may need each other"], answer: 3, explain: "Minerals are found in some places and not in others, so regions often depend on one another for them.", level: 3 }
    ],
    written: [
      { q: "Name two biotic resources.", a: "Any two of: forests, fish (or other living things such as cattle).", marks: 1 },
      { q: "What does 'reduce' mean in the 3 Rs?", a: "'Reduce' means to use fewer resources, for example by not wasting water or electricity.", marks: 1 },
      { q: "Write one difference between renewable and non-renewable resources, with an example of each.", a: "1. Renewable resources can be replaced naturally if used with care, for example wind or sunlight.\n2. Non-renewable resources take millions of years to form and can run out, for example coal or petroleum.", marks: 2 },
      { q: "Why is usable water called a limited resource?", a: "1. Most of the Earth's water is salty, so only a small part is usable.\n2. Its supply and demand differ from place to place and from season to season.", marks: 2 },
      { q: "Why is burning fossil fuels a matter of concern? Give two reasons.", a: "1. Fossil fuels are non-renewable and will run out because they take millions of years to form.\n2. Burning them adds carbon dioxide to the air.", marks: 2 },
      { q: "Explain the 3 Rs with one example of each.", a: "1. Reduce: use less, for example by switching off lights not in use.\n2. Reuse: use a thing again, for example using an old container to store food.\n3. Recycle: make waste into new products, for example melting waste glass to make new bottles.", marks: 3 },
      { q: "Suggest three practices by which a community can protect natural resources.", a: "Any three of:\n1. Rainwater harvesting to store rain.\n2. Drip irrigation to save water in farming.\n3. Planting trees to restore forests.\n4. Using public transport to save fuel.\n5. Shifting to solar and wind power.", marks: 3 },
      { q: "Case study: A village in a dry region collects rain from rooftops in tanks. The farmers have also stopped flooding their fields and use pipes that release water slowly near the plants. The panchayat has planted a new grove for every tree that was cut.\n(i) Name two practices from the passage that protect water.\n(ii) Are trees a renewable or a non-renewable resource?\n(iii) How do these steps help sustainable development?", a: "(i) Rainwater harvesting and drip irrigation.\n(ii) Trees are a renewable resource, because they can be replaced if used with care.\n(iii) They meet the present needs of the village while keeping water and forests for future generations.", marks: 4, type: "case" }
    ]
  },
  "reshaping-indias-political-map": {
    mcq: [
      { q: "The Delhi Sultanate came to an end in the year", options: ["1206", "1336", "1565", "1526"], answer: 3, explain: "The Sultanate lasted from 1206 until 1526, when Babur defeated Ibrahim Lodi at Panipat.", level: 1 },
      { q: "Which of these was NOT a dynasty of the Delhi Sultanate?", options: ["Khalji", "Tughluq", "Maurya", "Lodi"], answer: 2, explain: "The five dynasties were Mamluk, Khalji, Tughluq, Sayyid and Lodi. The Mauryas ruled much earlier.", level: 1 },
      { q: "On a map of southern India, Hampi, the capital of Vijayanagara, lies on the bank of the river", options: ["Ganga", "Tungabhadra", "Yamuna", "Narmada"], answer: 1, explain: "Hampi lies on the Tungabhadra river in the south.", level: 1 },
      { q: "Which ruler is the best known of the Vijayanagara Empire in the early 16th century?", options: ["Krishnadevaraya", "Alauddin Khalji", "Sher Shah Suri", "Babur"], answer: 0, explain: "Krishnadevaraya is the best-known Vijayanagara ruler. The others ruled in the north.", level: 1 },
      { q: "Sher Shah Suri introduced a silver coin called the", options: ["token coin", "gold dinar", "cowrie", "rupee"], answer: 3, explain: "Sher Shah introduced the silver rupee. Token currency was tried by Muhammad bin Tughluq.", level: 1 },
      { q: "Which statement about Alauddin Khalji is correct?", options: ["He founded the Mughal dynasty", "He kept a large standing army", "He built the capital at Hampi", "He fought at Talikota"], answer: 1, explain: "Alauddin Khalji expanded the Sultanate and kept a large standing army.", level: 2 },
      { q: "A student reads, 'The Sultan shifted his capital from Delhi to Daulatabad and tried token currency.'\nWhich Sultan and dynasty is meant?", options: ["Alauddin Khalji, Khalji dynasty", "Qutb-ud-din Aibak, Mamluk dynasty", "Muhammad bin Tughluq, Tughluq dynasty", "Ibrahim Lodi, Lodi dynasty"], answer: 2, explain: "Moving the capital to Daulatabad and token currency are linked with Muhammad bin Tughluq of the Tughluq dynasty.", level: 2 },
      { q: "Meera visits a ruined capital on the bank of the Tungabhadra, with grand temples, markets and water tanks.\nWhich empire's capital is it, and who founded the empire?", options: ["Bahmani kingdom; Muhammad bin Tughluq", "Delhi Sultanate; Aibak", "Mughal Empire; Babur", "Vijayanagara Empire; Harihara and Bukka"], answer: 3, explain: "Hampi was the capital of the Vijayanagara Empire, founded in 1336 by Harihara and Bukka.", level: 2 },
      { q: "In 1565 the Vijayanagara army was defeated at Talikota by", options: ["an alliance of Deccan sultanates", "the Mughals under Babur", "the Marathas under Shivaji", "Sher Shah Suri"], answer: 0, explain: "An alliance of Deccan sultanates defeated Vijayanagara at Talikota. Babur came in 1526 and Shivaji was born in 1630.", level: 2 },
      { q: "Under the mansabdari system, an official's mansab fixed his", options: ["religion and place of birth", "the river that watered his land", "status and the soldiers he kept", "the coins he could mint"], answer: 2, explain: "A mansab was a rank that fixed the official's status and the soldiers he had to keep.", level: 2 },
      { q: "Assertion (A): Hampi is remembered for its temples.\nReason (R): The Vijayanagara Empire was founded in 1336.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 1, explain: "Both statements are true, but the date of founding does not explain why Hampi is remembered for its temples.", level: 3, keepOrder: true },
      { q: "Which sequence lists these events in the correct time order?", options: ["Delhi Sultanate begins, Vijayanagara founded, First Battle of Panipat, Talikota", "Vijayanagara founded, Delhi Sultanate begins, Talikota, First Battle of Panipat", "Delhi Sultanate begins, First Battle of Panipat, Vijayanagara founded, Talikota", "First Battle of Panipat, Delhi Sultanate begins, Vijayanagara founded, Talikota"], answer: 0, explain: "The order is 1206, 1336, 1526 and 1565.", level: 3 },
      { q: "For how many years did the Delhi Sultanate last, from its founding to the First Battle of Panipat?", options: ["280 years", "310 years", "350 years", "320 years"], answer: 3, explain: "1526 − 1206 = 320 years.", level: 3 },
      { q: "Which pair is correctly matched?", options: ["Krishnadevaraya - Battle of Panipat", "Akbar - Battle of Talikota", "Alauddin Khalji - large standing army", "Babur - Daulatabad"], answer: 2, explain: "Alauddin Khalji kept a large standing army. Krishnadevaraya ruled Vijayanagara, Akbar followed Babur, and Daulatabad is linked to Muhammad bin Tughluq.", level: 3 }
    ],
    written: [
      { q: "Name the Sultan who shifted his capital from Delhi to Daulatabad.", a: "Muhammad bin Tughluq shifted the capital to Daulatabad.", marks: 1 },
      { q: "What is land revenue?", a: "Land revenue is the tax collected by the state from the produce of the land.", marks: 1 },
      { q: "Write two things for which Alauddin Khalji is known.", a: "1. He expanded the Delhi Sultanate.\n2. He kept a large standing army.", marks: 2 },
      { q: "Give two reasons why the Vijayanagara Empire is remembered.", a: "1. Its capital Hampi was famous for temples, trade and water management.\n2. Rulers such as Krishnadevaraya made it strong in the early 16th century.", marks: 2 },
      { q: "State two contributions of Sher Shah Suri.", a: "1. He improved the road that was later called the Grand Trunk Road.\n2. He introduced a silver coin called the rupee.", marks: 2 },
      { q: "Explain the mansabdari system of Akbar.", a: "1. Officials of the state were given ranks called mansabs.\n2. The rank fixed an official's status and the soldiers he kept.\n3. It helped Akbar organise the administration of his large empire.", marks: 3 },
      { q: "Give three facts about the beginning of Mughal rule.", a: "1. Babur defeated Ibrahim Lodi at the First Battle of Panipat in 1526.\n2. This ended the Delhi Sultanate.\n3. Akbar, who ruled from 1556, expanded the empire and organised its administration.", marks: 3 },
      { q: "Case study: A museum panel reads: 'In 1336 two founders set up a kingdom in the south. Its capital on the Tungabhadra river had grand temples, busy markets and well-planned water channels. Its best-known ruler governed in the early 16th century. In 1565 its army was defeated at Talikota.'\n(i) Name the empire and its founders.\n(ii) Name the capital and the best-known ruler.\n(iii) Who defeated its army in 1565?", a: "(i) The Vijayanagara Empire, founded by Harihara and Bukka.\n(ii) The capital was Hampi and the best-known ruler was Krishnadevaraya.\n(iii) An alliance of Deccan sultanates defeated it at the Battle of Talikota.", marks: 4, type: "case" }
    ]
  },
  "the-rise-of-the-marathas": {
    mcq: [
      { q: "Shivaji built his kingdom mainly by capturing hill forts in the", options: ["Eastern Ghats region of the south", "Aravalli hills of Rajasthan", "Western Ghats region of present-day Maharashtra", "Himalayan foothills"], answer: 2, explain: "Shivaji's kingdom grew in the Western Ghats region of present-day Maharashtra.", level: 1 },
      { q: "The Ashtapradhan was a council of how many ministers?", options: ["Five", "Eight", "Ten", "Twelve"], answer: 1, explain: "Ashtapradhan means a council of eight ministers who helped Shivaji govern.", level: 1 },
      { q: "Kanhoji Angre is remembered as a famous Maratha", options: ["admiral", "Peshwa", "court poet", "tax collector"], answer: 0, explain: "Kanhoji Angre was a Maratha admiral who protected the western coast.", level: 1 },
      { q: "Which ruler of Indore built temples, ghats and roads?", options: ["Tarabai", "Sambhaji", "Baji Rao I", "Ahilyabai Holkar"], answer: 3, explain: "Ahilyabai Holkar of Indore is remembered for her temples, ghats and roads.", level: 1 },
      { q: "Shivaji died in the year", options: ["1674", "1689", "1680", "1761"], answer: 2, explain: "Shivaji died in 1680. 1674 was his coronation and 1689 the year Sambhaji was executed.", level: 1 },
      { q: "Why could a smaller Maratha army trouble much larger forces?", options: ["It used quick surprise attacks and hill forts as bases", "It had more elephants than any enemy", "It never left the plains", "It fought only at sea"], answer: 0, explain: "Fast guerrilla warfare from strong hill forts let a smaller army strike and retreat.", level: 2 },
      { q: "A small kingdom next to Maratha territory is asked to pay a tax that the Marathas demanded from neighbouring areas.\nWhich demand is this?", options: ["Diwani", "Mansabdari", "Chauth and sardeshmukhi", "Doctrine of Lapse"], answer: 2, explain: "Chauth and sardeshmukhi were taxes the Marathas collected from neighbouring territories.", level: 2 },
      { q: "The Peshwas, who later became the real heads of the Maratha state, were originally", options: ["admirals of the navy", "village revenue collectors", "foreign traders", "chief ministers of the Maratha kings"], answer: 3, explain: "The Peshwa was the chief minister. Balaji Vishwanath was the first, and the office later held the real power.", level: 2 },
      { q: "Meena visits Raigad fort, where a guide says Shivaji was crowned in 1674.\nWhat title did he take at the coronation?", options: ["Sultan", "Chhatrapati", "Peshwa", "Badshah"], answer: 1, explain: "Shivaji took the title Chhatrapati, meaning a sovereign ruler.", level: 2 },
      { q: "Who led the Maratha resistance after Rajaram?", options: ["Tarabai", "Ahilyabai Holkar", "Balaji Vishwanath", "Kanhoji Angre"], answer: 0, explain: "Tarabai led the Maratha resistance after Rajaram.", level: 2 },
      { q: "Assertion (A): Forts were central to Maratha strategy.\nReason (R): The Marathas always fought open-field battles against larger armies.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 2, explain: "Forts were central, but the Marathas relied on guerrilla warfare and not on open-field battles against larger forces.", level: 3, keepOrder: true },
      { q: "Which sequence shows the events in the correct time order?", options: ["Third Battle of Panipat, Shivaji's coronation, Sambhaji's execution", "Sambhaji's execution, Shivaji's coronation, Third Battle of Panipat", "Shivaji's coronation, Third Battle of Panipat, Sambhaji's execution", "Shivaji's coronation, Sambhaji's execution, Third Battle of Panipat"], answer: 3, explain: "The coronation was in 1674, Sambhaji's execution in 1689, and the Third Battle of Panipat in 1761.", level: 3 },
      { q: "Shivaji was born in 1630, crowned in 1674 and died in 1680.\nHow old was he at death, and how many years after his coronation did he die?", options: ["44 years old; 6 years after", "56 years old; 6 years after", "50 years old; 6 years after", "50 years old; 16 years after"], answer: 2, explain: "1680 − 1630 = 50 years of age, and 1680 − 1674 = 6 years after the coronation.", level: 3 },
      { q: "Which statement about Maratha power after Shivaji is correct?", options: ["Peshwas, beginning with Balaji Vishwanath, held real power, and Maratha strength grew northwards under Baji Rao I before the defeat at Panipat in 1761", "The Marathas defeated Ahmad Shah Abdali at Panipat in 1761", "The Peshwas were rivals who fought against the Maratha kings", "Maratha power began only after 1761"], answer: 0, explain: "Power passed to the Peshwas, Baji Rao I expanded Maratha power to the north, and the Marathas lost to Ahmad Shah Abdali in 1761.", level: 3 }
    ],
    written: [
      { q: "Name the famous Maratha admiral who protected the western coast.", a: "Kanhoji Angre.", marks: 1 },
      { q: "Define guerrilla warfare.", a: "Guerrilla warfare is fighting by surprise attacks and quick retreats.", marks: 1 },
      { q: "What were chauth and sardeshmukhi?", a: "1. They were taxes the Marathas demanded from neighbouring territories.\n2. They added to the income of the Maratha state.", marks: 2 },
      { q: "Why did the Marathas build a navy? Name a famous admiral.", a: "1. The navy was built to protect the western coast.\n2. Kanhoji Angre later became a famous Maratha admiral.", marks: 2 },
      { q: "Who was Ahilyabai Holkar? State one of her achievements.", a: "1. She was a renowned ruler of Indore.\n2. She built temples, ghats and roads.", marks: 2 },
      { q: "How was Shivaji's kingdom governed and defended? Give three points.", a: "1. He had a council of eight ministers called the Ashtapradhan.\n2. The state collected chauth and sardeshmukhi from neighbouring territories.\n3. Hill forts and a navy protected the kingdom and the western coast.", marks: 3 },
      { q: "Describe how the Peshwas rose and how Maratha power in the north ended.", a: "1. The Peshwas were chief ministers, beginning with Balaji Vishwanath, and later held the real power.\n2. Baji Rao I greatly expanded Maratha power towards the north.\n3. In 1761 the Marathas were defeated by Ahmad Shah Abdali in the Third Battle of Panipat.", marks: 3 },
      { q: "Case study: Shivaji died in 1680 and his son Sambhaji ruled next. Sambhaji was executed by Aurangzeb in 1689, and Tarabai led the resistance after Rajaram. Later the Peshwas held the real power, and in 1761 the Marathas faced Ahmad Shah Abdali at Panipat.\n(i) Who executed Sambhaji, and in which year?\n(ii) Who led the Maratha resistance after Rajaram?\n(iii) Name the 1761 battle and say who won.", a: "(i) Aurangzeb executed Sambhaji in 1689.\n(ii) Tarabai.\n(iii) The Third Battle of Panipat, which was won by Ahmad Shah Abdali.", marks: 4, type: "case" }
    ]
  },
  "the-colonial-era-in-india": {
    mcq: [
      { q: "The Company received the Diwani of Bengal, Bihar and Orissa in", options: ["1757", "1764", "1765", "1793"], answer: 2, explain: "The Diwani, the right to collect revenue, was granted in 1765, after Plassey (1757) and Buxar (1764).", level: 1 },
      { q: "Tipu Sultan was the ruler of", options: ["Mysore", "Bengal", "Awadh", "Punjab"], answer: 0, explain: "Tipu Sultan ruled Mysore and was killed defending Seringapatam in 1799.", level: 1 },
      { q: "The Subsidiary Alliance is associated with", options: ["Lord Dalhousie", "Lord Wellesley", "Lord Cornwallis", "Macaulay"], answer: 1, explain: "Lord Wellesley used the Subsidiary Alliance. Dalhousie is linked to the Doctrine of Lapse and Cornwallis to the Permanent Settlement.", level: 1 },
      { q: "Under colonial rule India supplied raw materials such as", options: ["steel and cars", "machine tools", "aeroplanes", "cotton and indigo"], answer: 3, explain: "India supplied raw materials like cotton and indigo and became a market for British goods.", level: 1 },
      { q: "Macaulay's Minute of 1835 promoted", options: ["English-medium education", "revenue collection by zamindars", "the Permanent Settlement", "the Subsidiary Alliance"], answer: 0, explain: "The Minute promoted English-medium education.", level: 1 },
      { q: "Ravi's great-grandfather was a weaver who lost buyers as cheap factory cloth from Britain filled Indian markets.\nWhich feature of colonial rule explains this?", options: ["Indian handicrafts were helped by new railways", "Zamindars were removed from the revenue system", "India became a market for British goods, which hurt traditional handicrafts", "India stopped supplying raw materials"], answer: 2, explain: "Colonial rule made India a supplier of raw materials and a market for British goods, which hurt traditional handicrafts.", level: 2 },
      { q: "A peasant's crop fails, but the revenue demand remains high.\nWhat is he most likely to do?", options: ["Pay it from his savings", "Borrow money and fall into debt", "Become a zamindar", "Ask the Crown to cancel all revenue"], answer: 1, explain: "High revenue demands pushed many peasants into debt.", level: 2 },
      { q: "The Permanent Settlement of 1793 fixed", options: ["the price of cotton", "the number of soldiers", "the age of voters", "the revenue that zamindars paid"], answer: 3, explain: "Lord Cornwallis fixed the revenue that zamindars had to pay to the Company.", level: 2 },
      { q: "Which pair of policy and Governor-General is correctly matched?", options: ["Subsidiary Alliance - Wellesley", "Doctrine of Lapse - Cornwallis", "Permanent Settlement - Dalhousie", "Diwani - Macaulay"], answer: 0, explain: "Wellesley is linked with the Subsidiary Alliance, Dalhousie with the Doctrine of Lapse and Cornwallis with the Permanent Settlement.", level: 2 },
      { q: "Under a Subsidiary Alliance, an Indian ruler", options: ["could ask the Company for free soldiers", "paid tribute to the Mughals", "kept British troops and paid for them, losing independence in foreign affairs", "had to give up all his land at once"], answer: 2, explain: "The ruler maintained British troops at his own cost and lost his independence in foreign affairs.", level: 2 },
      { q: "Assertion (A): The grant of the Diwani in 1765 gave the Company financial power in eastern India.\nReason (R): The Diwani was the right to collect revenue in Bengal, Bihar and Orissa.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "Collecting the revenue of three rich provinces gave the Company large income, so R explains A.", level: 3, keepOrder: true },
      { q: "Which sequence is in the correct time order?", options: ["Permanent Settlement, Plassey, first railway, Macaulay's Minute", "Plassey, Permanent Settlement, Macaulay's Minute, first railway", "Macaulay's Minute, Plassey, first railway, Permanent Settlement", "Plassey, Macaulay's Minute, Permanent Settlement, first railway"], answer: 1, explain: "The order is 1757, 1793, 1835 and 1853.", level: 3 },
      { q: "How many years passed between the Battle of Plassey and the start of direct Crown rule?", options: ["91 years", "100 years", "107 years", "101 years"], answer: 3, explain: "1858 − 1757 = 101 years.", level: 3 },
      { q: "Which statement about 1857-58 is correct?", options: ["The Revolt was only by zamindars and the Company continued as before", "The Crown took control in 1757", "The Revolt involved soldiers, peasants and rulers, and in 1858 power passed from the Company to the Crown", "The Crown took control before the first railway ran"], answer: 2, explain: "The Revolt of 1857 involved many groups, and after it the British Crown took over in 1858. The first railway (1853) was earlier.", level: 3 }
    ],
    written: [
      { q: "What was the Diwani?", a: "The Diwani was the right to collect revenue in a province. The Company received it for Bengal, Bihar and Orissa in 1765.", marks: 1 },
      { q: "Who introduced the Permanent Settlement, and in which year?", a: "Lord Cornwallis introduced it in 1793.", marks: 1 },
      { q: "What was the Subsidiary Alliance?", a: "1. It was a treaty in which an Indian ruler kept British troops and paid for them.\n2. The ruler lost his independence in foreign affairs.", marks: 2 },
      { q: "How did colonial rule affect Indian handicrafts?", a: "1. India became a market for British goods.\n2. This hurt traditional handicrafts, while India was made to supply raw materials like cotton and indigo.", marks: 2 },
      { q: "Why were the Battles of Plassey and Buxar important?", a: "1. They gave the East India Company control over Bengal (1757 and 1764).\n2. In 1765 the Company received the Diwani of Bengal, Bihar and Orissa.", marks: 2 },
      { q: "Explain the Permanent Settlement and its effect on peasants.", a: "1. In 1793 Lord Cornwallis fixed the revenue that zamindars paid to the Company.\n2. High revenue demands pushed many peasants into debt.\n3. Other systems, the Ryotwari and Mahalwari, were used in other regions.", marks: 3 },
      { q: "What was Macaulay's Minute of 1835, and what was its result?", a: "1. It promoted English-medium education in India.\n2. It created a class of educated Indians.\n3. Many of them later led reform and national movements.", marks: 3 },
      { q: "Case study: The first railway in India ran in 1853 and mainly served trade and administration. At the same time, India supplied raw materials such as cotton and indigo, and bought British goods. In 1858 the British Crown took over from the Company.\n(i) Between which two places did the first railway run?\n(ii) Whose needs did the railways mainly serve?\n(iii) What two roles did India play in the colonial economy?", a: "(i) Between Bombay and Thane.\n(ii) The needs of trade and administration.\n(iii) India was a supplier of raw materials and a market for British goods.", marks: 4, type: "case" }
    ]
  },
  "universal-franchise-and-indias-electoral-system": {
    mcq: [
      { q: "The voting age in India was lowered from 21 to 18 by the", options: ["42nd Amendment", "61st Amendment", "44th Amendment", "1st Amendment"], answer: 1, explain: "The 61st Amendment (1988) lowered the voting age from 21 to 18.", level: 1 },
      { q: "India's first general elections were held in", options: ["1947", "1950", "1951-52", "1962"], answer: 2, explain: "The first general elections were held in 1951-52 after the Constitution came into force.", level: 1 },
      { q: "NOTA allows a voter to", options: ["reject all the candidates", "vote twice", "vote from home online", "choose the Prime Minister directly"], answer: 0, explain: "NOTA lets a voter say that none of the candidates is acceptable.", level: 1 },
      { q: "EVM stands for", options: ["Electoral Verification Method", "Election Voting Manual", "Equal Vote Machine", "Electronic Voting Machine"], answer: 3, explain: "EVM stands for Electronic Voting Machine, on which votes are cast.", level: 1 },
      { q: "A system in which the candidate who gets the most votes wins is called", options: ["proportional representation", "first-past-the-post", "nomination", "secret ballot"], answer: 1, explain: "In first-past-the-post, the candidate with the most votes in a constituency wins.", level: 1 },
      { q: "Why is voting done by secret ballot?", options: ["So that voters can choose without pressure from anyone", "So that results are declared faster", "So that candidates need not campaign", "So that only educated people vote"], answer: 0, explain: "Secrecy lets every voter choose freely, with no fear or pressure.", level: 2 },
      { q: "A month before the polls, a state government wants to announce a big new scheme for voters.\nWhich rule is meant to stop this?", options: ["Secret ballot", "The 61st Amendment", "VVPAT", "Model Code of Conduct"], answer: 3, explain: "The Model Code of Conduct applies from the announcement of elections until the results, and stops the government from announcing new schemes to influence voters.", level: 2 },
      { q: "Anil is 17 and wants to vote in the coming election.\nWhat is the position?", options: ["He can vote if his family is rich", "He can vote because every citizen can vote", "He cannot vote, as the voting age is 18 years", "He can vote if he can read"], answer: 2, explain: "The right to vote begins at 18, regardless of wealth or literacy.", level: 2 },
      { q: "Some constituencies are reserved for", options: ["candidates above 60", "Scheduled Castes and Scheduled Tribes", "government employees", "rural voters only"], answer: 1, explain: "Some constituencies are reserved for Scheduled Castes and Scheduled Tribes.", level: 2 },
      { q: "The Election Commission of India is headed by the", options: ["Chief Election Commissioner", "Speaker", "Chief Justice", "Governor"], answer: 0, explain: "The Chief Election Commissioner heads the independent Election Commission.", level: 2 },
      { q: "Assertion (A): Universal adult franchise gives rich and poor citizens an equal right to vote.\nReason (R): The right to vote depends on a person's caste and wealth.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 2, explain: "Every adult citizen can vote regardless of caste, religion, gender or wealth. So the assertion is true and the reason is false.", level: 3, keepOrder: true },
      { q: "Which set of facts about a Lok Sabha election is correct?", options: ["Voter 21 years; candidate 25 years; term 6 years", "Voter 18 years; candidate 21 years; term 5 years", "Voter 18 years; candidate 30 years; term 5 years", "Voter 18 years; candidate 25 years; term 5 years"], answer: 3, explain: "Voters must be at least 18, Lok Sabha candidates at least 25, and the term is five years unless dissolved earlier.", level: 3 },
      { q: "In a constituency three candidates get 42,000, 38,500 and 36,000 votes.\nWho wins under first-past-the-post?", options: ["The 38,500 candidate, as the middle value", "There is a second round, since nobody has more than half", "The candidate with 42,000 votes, even though that is less than half the total", "Nobody, since no candidate crossed 50,000"], answer: 2, explain: "The total is 1,16,500. The leader has 42,000, which is less than half, but under first-past-the-post the highest vote count wins.", level: 3 },
      { q: "Neha presses the button for her chosen candidate on the EVM.\nWhich step lets her check that her choice was recorded as she intended?", options: ["The electoral roll", "The VVPAT slip shown for a few seconds", "The Model Code of Conduct", "The NOTA button"], answer: 1, explain: "The VVPAT shows a slip for a few seconds so the voter can verify the choice.", level: 3 }
    ],
    written: [
      { q: "What is an electoral roll?", a: "The electoral roll is the list of eligible voters.", marks: 1 },
      { q: "State the minimum age to contest a Lok Sabha election.", a: "A candidate must be at least 25 years old.", marks: 1 },
      { q: "What is a secret ballot, and why is it important?", a: "1. A secret ballot means no one else knows whom a voter has voted for.\n2. It lets people choose freely, without pressure or fear.", marks: 2 },
      { q: "Name the four offices or bodies for whose elections the Election Commission is responsible.", a: "Parliament, the State Assemblies, the office of the President and the office of the Vice President.", marks: 2 },
      { q: "What is the difference between an EVM and a VVPAT?", a: "1. An EVM is the machine on which a voter casts the vote.\n2. A VVPAT shows the voter a paper slip for a few seconds to verify the vote cast.", marks: 2 },
      { q: "What is the Model Code of Conduct? Why is it needed?", a: "1. It is a set of rules for parties and candidates, applying from the announcement of elections until the results.\n2. For example, the government cannot announce new schemes to influence voters.\n3. It is needed to keep elections free and fair.", marks: 3 },
      { q: "What is a constituency? How is the winner decided and what are reserved constituencies?", a: "1. A constituency is an area whose voters elect one representative.\n2. The candidate with the most votes wins (first-past-the-post).\n3. Some constituencies are reserved for Scheduled Castes and Scheduled Tribes.", marks: 3 },
      { q: "Case study: Priya, who is 19, votes for the first time. She checks her name on the electoral roll and carries an identity proof. She presses a button on the EVM and sees a slip for a few seconds. Her 17-year-old neighbour cannot vote.\n(i) Why can the neighbour not vote?\n(ii) What is the purpose of the slip Priya saw?\n(iii) Which principle ensures that Priya's vote counts as much as any other voter's?", a: "(i) The minimum voting age is 18 years.\n(ii) The VVPAT slip lets the voter verify the vote cast on the EVM.\n(iii) The principle of one person, one vote, in which every vote has equal value.", marks: 4, type: "case" }
    ]
  },
  "the-parliamentary-system": {
    mcq: [
      { q: "The Parliament of India consists of", options: ["Lok Sabha and Rajya Sabha only", "the President, Lok Sabha and Rajya Sabha", "the Prime Minister and the Council of Ministers", "the Supreme Court, Lok Sabha and Rajya Sabha"], answer: 1, explain: "Parliament has three parts: the President, the Lok Sabha and the Rajya Sabha.", level: 1 },
      { q: "The chairperson of the Rajya Sabha is the", options: ["Speaker", "President", "Vice President", "Prime Minister"], answer: 2, explain: "The Vice President is the chairperson of the Rajya Sabha. The Speaker presides over the Lok Sabha.", level: 1 },
      { q: "The normal term of the Lok Sabha is", options: ["three years", "four years", "six years", "five years"], answer: 3, explain: "Lok Sabha members are elected for five years unless the House is dissolved earlier.", level: 1 },
      { q: "A draft of a proposed law is called a", options: ["Bill", "Act", "charter", "warrant"], answer: 0, explain: "A proposed law is a Bill. It becomes an Act after both Houses pass it and the President assents.", level: 1 },
      { q: "Question Hour is used by members to", options: ["elect the President", "approve a Money Bill without debate", "ask ministers questions and hold them accountable", "choose the Speaker"], answer: 2, explain: "In Question Hour members question ministers about their work.", level: 1 },
      { q: "A person must be at least how many years old to be a member of the Rajya Sabha?", options: ["25", "30", "35", "21"], answer: 1, explain: "The minimum age is 30 for the Rajya Sabha and 25 for the Lok Sabha.", level: 2 },
      { q: "In a general election a party wins 280 of the 543 elected Lok Sabha seats.\nWhat will most likely happen?", options: ["The Rajya Sabha will choose the Prime Minister", "The party must wait until it has 400 seats", "The Speaker will become the Prime Minister", "The party's leader will usually be appointed Prime Minister"], answer: 3, explain: "A party with at least 272 seats has a majority, and its leader is usually appointed Prime Minister.", level: 2 },
      { q: "A government loses the confidence of the Lok Sabha.\nWhat must the Council of Ministers do?", options: ["Dissolve the Rajya Sabha", "Continue as if nothing happened", "Resign", "Ask the Rajya Sabha to approve a new Prime Minister"], answer: 2, explain: "The Council of Ministers is collectively responsible to the Lok Sabha, so it must resign if it loses the House's confidence.", level: 2 },
      { q: "Which statement about the Rajya Sabha is correct?", options: ["Its members are directly elected by all adult citizens", "Its members are mostly elected by State Legislative Assemblies", "It is presided over by the Speaker", "It is dissolved every five years"], answer: 1, explain: "Rajya Sabha members are mostly elected by State Legislative Assemblies. It is a permanent house.", level: 2 },
      { q: "The formal head of state in India is", options: ["the President", "the Prime Minister", "the Speaker", "the Chief Justice"], answer: 0, explain: "The President is the formal head, while real powers are exercised by the Prime Minister and the Council of Ministers.", level: 2 },
      { q: "Assertion (A): The Council of Ministers must resign if it loses the confidence of the Lok Sabha.\nReason (R): The Council of Ministers is collectively responsible to the Lok Sabha.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "Because the ministers are collectively answerable to the Lok Sabha, the loss of its confidence forces the government to resign.", level: 3, keepOrder: true },
      { q: "Which is the correct path for an ordinary Bill to become law?", options: ["President's assent, then both Houses pass it, then it is an Act", "Only the Lok Sabha passes it, then the Speaker assents, then it is an Act", "Both Houses discuss and pass the Bill, then the President assents, then it is an Act", "The Rajya Sabha passes it, then the Prime Minister assents, then it is an Act"], answer: 2, explain: "A Bill must pass both Houses and then receive the President's assent to become an Act.", level: 3 },
      { q: "Which of these belongs to the permanent executive?", options: ["The Prime Minister", "The Finance Minister", "The Speaker", "A civil servant who runs a ministry's day-to-day work"], answer: 3, explain: "The permanent executive is made up of civil servants who carry out policy even when governments change. Ministers are the political executive.", level: 3 },
      { q: "Party A wins 255 seats and allies with two parties that have 20 and 9 seats. A majority in the Lok Sabha needs 272 of 543.\nDoes the alliance have a majority?", options: ["No, it needs at least 300 seats", "No, it needs all 543 seats", "Yes, 284 seats, which is 12 more than 272", "Yes, 275 seats, which is just above 272"], answer: 2, explain: "255 + 20 + 9 = 284, and 284 − 272 = 12, so the alliance has a majority.", level: 3 }
    ],
    written: [
      { q: "How many members of the Lok Sabha are elected from constituencies?", a: "543 members are elected from constituencies.", marks: 1 },
      { q: "Which House has the final say on a Money Bill?", a: "The Lok Sabha, where Money Bills are introduced.", marks: 1 },
      { q: "Name the three parts of the Parliament.", a: "The President, the Lok Sabha and the Rajya Sabha.", marks: 2 },
      { q: "Write two differences between the Lok Sabha and the Rajya Sabha.", a: "1. Lok Sabha members are directly elected by the people, whereas Rajya Sabha members are mostly elected by State Legislative Assemblies.\n2. The Lok Sabha has a term of five years, while the Rajya Sabha is a permanent house in which one-third of its members retire every two years.", marks: 2 },
      { q: "What is Question Hour? Why is it important?", a: "1. In Question Hour members of Parliament ask ministers questions about their work.\n2. It holds ministers accountable to Parliament.", marks: 2 },
      { q: "Describe how an ordinary Bill becomes an Act. How is a Money Bill different?", a: "1. A Bill is discussed and voted on in both Houses.\n2. After both Houses pass it, the President's assent turns it into an Act.\n3. A Money Bill, dealing with taxes and spending, is introduced only in the Lok Sabha, which has the final say.", marks: 3 },
      { q: "Distinguish between the President, the Prime Minister with the Council of Ministers, and the permanent executive.", a: "1. The President is the formal head of state.\n2. The Prime Minister and the Council of Ministers exercise real powers and are collectively responsible to the Lok Sabha.\n3. The permanent executive of civil servants carries out policy day to day, even when governments change.", marks: 3 },
      { q: "Case study: After a general election an alliance wins 290 of the 543 elected Lok Sabha seats and its leader is appointed Prime Minister. In Question Hour a member asks a minister why a road project is delayed.\n(i) Why is the alliance's leader appointed Prime Minister?\n(ii) What is the purpose of the member's question?\n(iii) What must the Council of Ministers do if it loses the confidence of the Lok Sabha?", a: "(i) The alliance has 290 seats, which is more than the 272 needed for a majority.\n(ii) To hold the minister accountable for the work of the government.\n(iii) It must resign, because it is collectively responsible to the Lok Sabha.", marks: 4, type: "case" }
    ]
  },
  "factors-of-production": {
    mcq: [
      { q: "The reward for the use of land is called", options: ["wages", "rent", "interest", "profit"], answer: 1, explain: "Land earns rent. Wages go to labour, interest to capital and profit to the entrepreneur.", level: 1 },
      { q: "Which of these is a factor of production?", options: ["Labour", "Competition", "Taxation", "Barter"], answer: 0, explain: "The four factors are land, labour, capital and entrepreneurship.", level: 1 },
      { q: "Machines, tools and buildings are examples of", options: ["land", "labour", "capital", "entrepreneurship"], answer: 2, explain: "Capital is man-made resources used to produce more goods.", level: 1 },
      { q: "The person who organises production and takes the risk is the", options: ["worker", "landowner", "lender", "entrepreneur"], answer: 3, explain: "The entrepreneur organises the other factors, takes risks and earns profit.", level: 1 },
      { q: "The skills and health of people, built through education and training, are called", options: ["human capital", "fixed capital", "working capital", "rent"], answer: 0, explain: "Human capital means the knowledge, skills and health of people.", level: 1 },
      { q: "Raw materials and cash that are used up or turned over in production are called", options: ["fixed capital", "working capital", "human capital", "land"], answer: 1, explain: "Working capital is used up in each cycle. Fixed capital, like a machine, lasts through many cycles.", level: 2 },
      { q: "Gurmeet runs a bakery with an oven, two hired bakers, a rented shop and a stock of flour.\nWhich of these is fixed capital?", options: ["The oven", "The flour", "Cash kept for wages", "The skill of the bakers"], answer: 0, explain: "The oven is used again and again. Flour and cash are used up, and skill is human capital.", level: 2 },
      { q: "Farmer Hardev lends money to a shopkeeper and receives a yearly payment for it.\nWhat is this payment called?", options: ["Rent", "Profit", "Wages", "Interest"], answer: 3, explain: "The reward for capital is interest.", level: 2 },
      { q: "When workers receive training, which aspect of the labour factor improves?", options: ["The amount of land available", "The rate of interest", "The quality and skill of labour", "The number of machines"], answer: 2, explain: "Training raises skills, which raises productivity.", level: 2 },
      { q: "Which of these is an example of land as a factor of production?", options: ["A river used for irrigation", "A tractor", "A farmer's skill", "A bank loan"], answer: 0, explain: "Land includes all natural resources such as soil, water, forests and minerals.", level: 2 },
      { q: "Assertion (A): Land alone can produce goods without the other factors.\nReason (R): All the factors of production are needed together.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 3, explain: "Even a farm needs workers, tools, seeds and someone to plan and take the risk. The assertion is false and the reason is true.", level: 3, keepOrder: true },
      { q: "Which pair contains one item of fixed capital and one of working capital?", options: ["A tractor and a farm shed", "A tractor and fertiliser", "Seeds and fertiliser", "Cash for wages and seeds"], answer: 1, explain: "The tractor is fixed capital and the fertiliser is used up, so it is working capital. The other pairs are both fixed or both working.", level: 3 },
      { q: "Which pair of factor and reward is correctly matched?", options: ["Land - interest, capital - rent", "Labour - wages, entrepreneurship - profit", "Capital - profit, labour - rent", "Land - wages, entrepreneurship - interest"], answer: 1, explain: "Land earns rent, labour wages, capital interest and the entrepreneur profit.", level: 3 },
      { q: "A tailor spends ₹12,000 on a sewing machine and ₹5,000 on cloth and thread.\nWhich statement is correct?", options: ["Fixed capital ₹5,000; working capital ₹12,000", "All ₹17,000 is fixed capital", "Fixed capital ₹12,000; working capital ₹5,000", "All ₹17,000 is working capital"], answer: 2, explain: "The machine is used for many rounds of production, and cloth and thread are used up. The total is 12,000 + 5,000 = ₹17,000.", level: 3 }
    ],
    written: [
      { q: "Define production.", a: "Production is making goods and services that satisfy human wants.", marks: 1 },
      { q: "What is human capital?", a: "Human capital means the knowledge, skills and health of people, built through education and training.", marks: 1 },
      { q: "Give two examples of land as a factor of production and name its reward.", a: "1. Examples: soil, water, forests or minerals.\n2. The reward for land is rent.", marks: 2 },
      { q: "How can education and training raise production?", a: "1. They improve the quality and skill of labour, which adds to human capital.\n2. Skilled workers produce more, so productivity rises.", marks: 2 },
      { q: "How does technology help production?", a: "1. Technology and better tools raise the output from the same inputs.\n2. So more goods can be produced with the same land, labour and capital.", marks: 2 },
      { q: "Who is an entrepreneur? Explain his role with an example.", a: "1. An entrepreneur starts the enterprise and organises land, labour and capital.\n2. He takes the risk, for example a person who starts a bakery.\n3. His reward is profit.", marks: 3 },
      { q: "Using a farm as an example, show how the four factors of production work together.", a: "1. Land: the field and water.\n2. Labour: the workers who sow and harvest, and capital: tools, seeds and money.\n3. The entrepreneur plans the farm and takes the risk. All four are needed together.", marks: 3 },
      { q: "Case study: Sukhdev takes a bank loan and rents a plot. He buys milking machines and fodder, hires two workers, and himself organises the dairy and bears the risk.\n(i) Who is the entrepreneur and what is his reward?\n(ii) Name one item of fixed capital and one of working capital.\n(iii) Name the reward paid for the plot, the workers and the loan.", a: "(i) Sukhdev is the entrepreneur, and his reward is profit.\n(ii) Fixed capital: the milking machines. Working capital: the fodder.\n(iii) Rent for the plot, wages for the workers and interest for the loan.", marks: 4, type: "case" }
    ]
  },
  "world-geography-some-glimpses": {
    mcq: [
      { q: "How many continents are there on the Earth?", options: ["5", "6", "7", "8"], answer: 2, explain: "There are seven continents: Asia, Africa, North America, South America, Antarctica, Europe and Australia (Oceania).", level: 1 },
      { q: "Which ocean is both the largest and the deepest?", options: ["Atlantic", "Pacific", "Indian", "Southern"], answer: 1, explain: "The Pacific Ocean is the largest and deepest, and it contains the Mariana Trench.", level: 1 },
      { q: "On a world map, a long mountain chain runs down the western side of South America. It is the", options: ["Alps", "Rockies", "Himalayas", "Andes"], answer: 3, explain: "The Andes run along the western side of South America. The Rockies are in North America.", level: 1 },
      { q: "The river Nile flows in the continent of", options: ["Africa", "Asia", "Europe", "South America"], answer: 0, explain: "The Nile is a great river of Africa.", level: 1 },
      { q: "The Mariana Trench lies in the", options: ["Atlantic Ocean", "Arctic Ocean", "Pacific Ocean", "Indian Ocean"], answer: 2, explain: "The Mariana Trench in the Pacific is the deepest known part of the ocean.", level: 1 },
      { q: "The Alps are a mountain range in", options: ["Asia", "Europe", "Africa", "North America"], answer: 1, explain: "The Alps are in Europe.", level: 2 },
      { q: "A traveller sees dense, warm and wet forest with very tall trees near the Equator.\nWhich natural region is this?", options: ["Tundra", "Hot desert", "Temperate grassland", "Tropical rainforest"], answer: 3, explain: "Tropical rainforests are found near the Equator.", level: 2 },
      { q: "A photograph shows a cold, treeless landscape with mosses and lichens, and people wearing heavy clothes.\nWhich natural region is this?", options: ["Tundra", "Savanna", "Hot desert", "Tropical rainforest"], answer: 0, explain: "Tundra is a cold, treeless region near the poles with mosses and lichens.", level: 2 },
      { q: "The Equator divides the Earth into the", options: ["Northern and Southern Hemispheres", "Eastern and Western Hemispheres", "Asia and Europe", "land and water"], answer: 0, explain: "The Equator at 0° latitude divides the Earth into the Northern and Southern Hemispheres.", level: 2 },
      { q: "Which continent has no permanent population?", options: ["Australia", "Europe", "Antarctica", "Africa"], answer: 2, explain: "Antarctica is the coldest continent and has no permanent population.", level: 2 },
      { q: "Assertion (A): Tropical rainforests are found near the Equator.\nReason (R): Tundra regions are found near the poles.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 1, explain: "Both statements are true, but the location of the tundra does not explain why rainforests lie near the Equator.", level: 3, keepOrder: true },
      { q: "Which pair of river and continent is correctly matched?", options: ["Andes - Europe", "Yangtze - Africa", "Mississippi - North America", "Amazon - Asia"], answer: 2, explain: "The Mississippi is in North America. The Yangtze is in Asia and the Amazon in South America; the Andes are a mountain range.", level: 3 },
      { q: "Which statement about the highest peak and the deepest trench is correct?", options: ["Everest is in the Alps of Europe, and the trench is in the Atlantic", "Everest is in the Andes, and the trench is in the Pacific", "Everest is in the Himalayas of Asia, and the trench is in the Indian Ocean", "Everest is in the Himalayas of Asia, and the trench is in the Pacific Ocean"], answer: 3, explain: "Mount Everest is the highest peak, in the Himalayas of Asia, and the Mariana Trench lies in the Pacific.", level: 3 },
      { q: "Region X is a hot desert with very little rain, while region Y is a tropical rainforest near the Equator.\nWhich statement is most likely true?", options: ["X has dense forest cover", "Growing crops that need much water is easier in Y than in X", "Y gets very little rain", "People in X need no water"], answer: 1, explain: "The rainforest gets plenty of rain and a desert gets very little, so water-loving crops are easier to grow in Y.", level: 3 }
    ],
    written: [
      { q: "Name the highest peak above sea level.", a: "Mount Everest.", marks: 1 },
      { q: "What is the Equator?", a: "The Equator is the imaginary line at 0° latitude that divides the Earth into the Northern and Southern Hemispheres.", marks: 1 },
      { q: "Name the continent of each mountain range: Himalayas, Andes, Rockies and Alps.", a: "Himalayas - Asia; Andes - South America; Rockies - North America; Alps - Europe.", marks: 2 },
      { q: "Name four great rivers of the world with the continent of each.", a: "The Nile - Africa; the Amazon - South America; the Mississippi - North America; the Yangtze - Asia.", marks: 2 },
      { q: "Describe the tundra region.", a: "1. It is a cold, treeless region near the poles.\n2. It has mosses and lichens, and people there need heavy clothing.", marks: 2 },
      { q: "Describe the savanna and hot desert regions, giving an example of a hot desert.", a: "1. A savanna is a tropical grassland with scattered trees.\n2. A hot desert receives very little rainfall.\n3. The Sahara in Africa is a hot desert.", marks: 3 },
      { q: "How do latitude and altitude affect the natural regions of the world? Give three points.", a: "1. Climate and vegetation vary with latitude, for example tropical rainforests lie near the Equator and tundra near the poles.\n2. They also vary with altitude.\n3. Plants, animals and the way people live, such as their food, housing and clothes, depend on the natural region.", marks: 3 },
      { q: "Case study: Rohit studies an atlas. He finds the largest continent and the largest ocean. In South America he traces a long mountain range and a great river. Near the poles he finds a cold, treeless region.\n(i) Name the largest continent and the largest ocean.\n(ii) Name a mountain range and a great river of South America.\n(iii) Name the cold, treeless natural region.", a: "(i) Asia is the largest continent and the Pacific is the largest ocean.\n(ii) The Andes mountains and the Amazon river.\n(iii) The tundra.", marks: 4, type: "case" }
    ]
  }
});
